<div class="checkout-layout"><div><section class="panel"><p class="eyebrow">Customer account</p><h1>Hello, <?= e($customer['name']) ?></h1><?php if($error): ?><div class="store-error" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" class="checkout-form"><?= $csrf->field() ?><label>Full name<input name="name" required maxlength="190" autocomplete="name" value="<?= e_attr($customer['name']) ?>"></label><label>Email address<input value="<?= e_attr($customer['email']) ?>" readonly aria-readonly="true"></label><label>Phone number<input name="phone" maxlength="60" autocomplete="tel" value="<?= e_attr($customer['phone']??'') ?>"></label><button class="btn">Save profile</button></form></section><section class="panel" style="margin-top:1rem"><h2>Order history</h2><?php if(!$orders): ?><p class="muted">No orders are connected to this account yet.</p><?php else: ?><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left">Order</th><th>Status</th><th>Payment</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><strong><?= e($order['order_number']) ?></strong></td><td><?= e(ucfirst($order['status'])) ?></td><td><?= e(ucfirst($order['payment_status'])) ?></td><td><?= e($order['currency']) ?> $<?= number_format((int)$order['total_minor']/100,2) ?></td><td><?= e($order['placed_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div><aside class="panel summary"><h2>Account</h2><p class="muted">Member since <?= e(date('M j, Y',strtotime($customer['created_at']))) ?></p><?php if(!empty($commerceAvailable)): ?><a class="btn" href="<?= e_attr($basePath) ?>/store">Start an order</a><?php endif; ?><form method="post" action="<?= e_attr($basePath) ?>/account/logout" style="margin-top:.8rem"><?= $csrf->field() ?><button class="btn secondary">Sign out</button></form></aside></div>
